    <section v-if="['home','counseling','providers','about','tutoring'].includes(section)" class="nlu-wrap nlu-section" data-analytics-id="providers"><div class="nlu-heading-row"><div><p class="nlu-eyebrow">Our providers</p><h2>A Team That Cares</h2></div><router-link v-if="section!=='providers'" :to="path('providers')">Meet our providers →</router-link></div><div class="nlu-provider-controls"><label>Service<select v-model="providerType" aria-label="Service"><option value="counseling">Counseling</option><option value="tutoring">Tutoring</option></select></label><label v-if="section==='providers'">Search providers<input v-model="search" type="search" placeholder="Search by name, specialty, or subject"/></label><router-link :to="`/nlu/find-${providerType==='tutoring'?'tutor':'counselor'}`">Full directory & availability →</router-link></div><p v-if="providersLoading" role="status">Loading providers…</p><p v-else-if="providersError" role="alert">Provider information is temporarily unavailable. <button @click="loadProviders">Try again</button></p><div v-else-if="visibleProviders.length" class="nlu-provider-grid"><article v-for="p in visibleProviders" :key="p.id" class="nlu-card nlu-provider" :data-analytics-id="'provider-'+providerType+'-'+p.id"><img v-if="safe(p.profilePhotoUrl)" :src="safe(p.profilePhotoUrl)" :alt="p.displayName" loading="lazy"/><div v-else class="nlu-avatar" aria-hidden="true"><Icon name="people"/></div><h3>{{p.displayName}}</h3><p>{{p.title}}</p><p class="nlu-provider-bio">{{p.profile?.publicBlurb||p.tutoringProfile?.bio||''}}</p><div class="nlu-tags"><span v-for="tag in providerTags(p)" :key="tag">{{tag}}</span></div><router-link class="nlu-button" :to="`/nlu/provider/${p.id}?serviceType=${providerType}`">View profile →</router-link></article></div><p v-else>Our provider profiles are being updated. <router-link :to="path('contact')">Contact our team for help finding support.</router-link></p></section>

    <section v-if="section==='get-started'" id="start" class="nlu-wrap nlu-section" data-analytics-id="enrollment"><div class="nlu-section-heading"><h2>Tell Us Where You’d Like to Start</h2><p>Choose a service to open its enrollment options. If you’re unsure, our team can help.</p></div><div class="nlu-three"><article class="nlu-card"><Icon name="school"/><h3>Start tutoring</h3><p>Share your student’s learning needs and goals.</p><router-link class="nlu-button" to="/join/nlu/tutoring">Tutoring enrollment →</router-link></article><article class="nlu-card"><Icon name="heart"/><h3>Start counseling</h3><p>Explore counseling and complete your intake.</p><router-link class="nlu-button" to="/join/nlu/counseling">Counseling enrollment →</router-link></article><article class="nlu-card"><Icon name="chat"/><h3>Explore combined support</h3><p>Talk about academic and emotional needs together.</p><router-link class="nlu-button" :to="path('contact')">Talk with our team →</router-link></article></div></section>

    <section v-if="['get-started','resources'].includes(section)" class="nlu-wrap nlu-section" data-analytics-id="family-resources"><h2>What Families May Need Before Starting</h2><div class="nlu-four"><router-link v-for="[title,to,icon] in resourceLinks" :key="title" class="nlu-card nlu-resource" :to="to"><Icon :name="icon"/><h3>{{title}}</h3><span aria-hidden="true">→</span></router-link></div><div id="insurance" class="nlu-note"><h3>Insurance & Billing</h3><p>Check the provider’s profile and ask our team about coverage, costs, and self-pay options. Insurance coverage for counseling does not automatically include tutoring.</p><router-link :to="path('contact')">Ask our team →</router-link></div><h2 id="faqs" class="nlu-space">Parent FAQs</h2><details v-for="[question,answer] in nluFaqs" :key="question" class="nlu-faq"><summary>{{question}} <span aria-hidden="true">+</span></summary><p>{{answer}}</p></details></section>

    <section v-if="section==='contact'" class="nlu-wrap nlu-section nlu-contact" data-analytics-id="contact"><h2>Message Our Team</h2><p>Our support team can help with service questions and next steps.</p><PublicAgencySupportForm v-if="!preview" agency-slug="nlu" join-path="/p/nlu/get-started" login-path="/nlu/login" accent="#087f8c"/><p v-else class="nlu-note">Open the published website to send a message.</p></section>

    <section v-if="section!=='contact'" class="nlu-final" :style="bannerStyle" data-analytics-id="footer-cta"><div class="nlu-wrap"><div><p class="nlu-eyebrow">Higher potential. Brighter tomorrows.</p><h2>{{section==='learning-center'?'Start With the Learner. Build the Path.':'Help Your Student Reach the Next Level.'}}</h2><p>Academic support. Emotional support. A path forward.</p><div class="nlu-actions"><router-link class="nlu-button" :to="path('get-started')">Get started →</router-link><router-link class="nlu-button nlu-outline" :to="path('contact')">Talk with our team →</router-link></div></div><p class="nlu-script">Higher potential<br/>starts here.</p></div></section>
