  <footer class="nlu-footer"><div class="nlu-wrap"><router-link to="/p/nlu"><img :src="asset('logo.png')" alt="Next Level Up"/></router-link><nav aria-label="Footer"><router-link v-for="[label,to] in footerNav" :key="to" :to="to.startsWith('/')?to:path(to)">{{label}}</router-link></nav><small>© {{new Date().getFullYear()}} Next Level Up Learning and Counseling Centers.</small></div></footer>
  <router-link v-if="section!=='contact'" class="nlu-support" :to="path('contact')"><Icon name="chat"/>Talk with our team</router-link>
  <p v-if="previewNotice" class="nlu-preview-notice" role="status">{{previewNotice}}</p>
 </div>
</template>
<script setup>
import { computed,ref,watch,onMounted,onUnmounted } from 'vue';
import api from '../../services/api';
import Icon from '../../components/rise/RiseIcon.vue';
import PublicResourcesMenu from '../../components/public/PublicResourcesMenu.vue';
import PublicAgencySupportForm from '../../components/public/PublicAgencySupportForm.vue';
import {useStandalonePublicWebsite,publicWebsiteUrl as safe} from '../../composables/useStandalonePublicWebsite';
import {nluHeroes,nluServices,nluSteps,nluLearning,nluSkills,nluFaqs,nluFamilies} from '../../constants/nluWebsite';
const {route,page,loading,error,menuOpen,settings,path,load,preview,previewNotice,guardPreview}=useStandalonePublicWebsite('nlu','Next Level Up | Learning and Counseling Centers');
const aliases={'':'home','therapy-plus-tutoring':'therapy-tutoring','cognitive-emotional-enrichment':'therapy-tutoring','programs':'learning-center','next-level-learning-center':'learning-center','academic-acceleration-program':'academic-acceleration','for-families':'resources','join':'get-started'};
const section=computed(()=>aliases[String(route.params.section||'')]||String(route.params.section));
const asset=name=>'/assets/nlu/'+name;
const hero=computed(()=>{const h=nluHeroes[section.value];if(!h)return null;const custom=settings.value.pages?.[section.value]||{};return{eyebrow:custom.eyebrow||h[0],title:custom.title||(section.value==='home'?page.value?.heroTitle:null)||h[1],subtitle:custom.subtitle||h[2],body:custom.body||(section.value==='home'?page.value?.heroSubtitle:null)||h[3],image:safe(custom.imageUrl)||(section.value==='home'?safe(page.value?.heroImageUrl):'')||asset(h[4])};});
const heroStyle=computed(()=>({'--nlu-hero':`url(${JSON.stringify(hero.value?.image||'')})`}));
const bannerStyle=computed(()=>({'--nlu-banner':`url("${safe(settings.value.ctaImageUrl)||asset('mountains.png')}")`}));
const nav=[['Home',''],['Tutoring','tutoring'],['Counseling','counseling'],['Therapy + Tutoring','therapy-tutoring'],['Programs','learning-center'],['Providers','providers']];
const footerNav=[...nav,['About','about'],['How it works','how-it-works'],['Get started','get-started'],['Contact','contact'],['Careers','/careers/nlu'],['Client portal','/nlu/login'],['Privacy','/nlu/privacypolicy'],['Terms','/nlu/terms']];
const trust=[['people','Individualized support','Tailored to the student'],['heart','Family-centered care','We’re in this together'],['shield','Qualified providers','Support matched to your needs'],['screen','Flexible options','In-person and virtual care']];
const tutoringValues=[['target','Targeted instruction'],['leaf','Skill development'],['calendar','Repeated practice'],['chart','Strategy building'],['shield','Progress monitoring'],['people','Parent communication']];
const counselingAreas=[['heart','Emotional Support',['Stress and worry','Mood concerns','Confidence and self-esteem','Coping with overwhelm']],['target','Behavior & Regulation',['Emotional regulation','Frustration tolerance','Coping skills','Behavior challenges']],['school','School & Life Challenges',['School stress','Social skills','Life transitions','Family changes']]];
const studentPaths=[['Mostly tutoring','A student who needs help with reading, math, or study skills may work with a tutor on academic goals.'],['Coordinated support','A student facing both academic and emotional challenges may benefit from an integrated plan.'],['Mostly counseling','A student navigating stress or life changes may begin with counseling and add academic support as needed.']];
const providerRoles=[['Academic & skills specialists','Academic instruction, study strategies, organization, and learning support.'],['Behavioral health providers','Skill development and behavioral support within their qualifications and supervision requirements.'],['Counselors & therapists','Clinical support delivered by appropriately qualified professionals, with supervision when required.']];
const resourceLinks=[['New family information',path('get-started'),'people'],['Forms & enrollment',path('get-started#start'),'calendar'],['Find a provider',path('providers'),'target'],['Client portal','/nlu/login','screen']];
const header=ref(),menuButton=ref(),familiesButton=ref(),familiesOpen=ref(false);
function hoverFamilies(){if(window.innerWidth>1100&&window.matchMedia('(hover: hover)').matches)familiesOpen.value=true;}
function closeNavigation(){familiesOpen.value=false;menuOpen.value=false;(window.innerWidth<=1100?menuButton:familiesButton).value?.focus();}
function leaveFamilies(e){if(!e.currentTarget.contains(document.activeElement))familiesOpen.value=false;}
function leaveHeader(e){if(!header.value?.contains(e.relatedTarget))familiesOpen.value=false;}
function outside(e){if(!header.value?.contains(e.target))familiesOpen.value=false;}
function previewClick(e){if(preview&&e.target.closest('a')&&!e.target.closest('a').getAttribute('href')?.startsWith('/p/nlu'))guardPreview(e);}
const providerType=ref('counseling'),providers=ref([]),providersLoading=ref(false),providersError=ref(false),search=ref('');let providerGeneration=0;
const providerTags=p=>[...new Set(providerType.value==='tutoring'?(p.tutoringProfile?.subjectAreas||[]):p.specialties||[])].slice(0,3);
const visibleProviders=computed(()=>{const q=search.value.toLowerCase().trim();const list=providers.value.filter(p=>!q||`${p.displayName} ${p.title} ${providerTags(p).join(' ')}`.toLowerCase().includes(q));return section.value==='providers'?list:list.slice(0,4);});
async function loadProviders(){const id=++providerGeneration;providers.value=[];providersLoading.value=true;providersError.value=false;try{const{data}=await api.get(`/public/agency-services/nlu/${providerType.value==='tutoring'?'tutors':'counselors'}`,{skipAuthRedirect:true,skipGlobalLoading:true});if(id===providerGeneration)providers.value=data.providers||[];}catch{if(id===providerGeneration)providersError.value=true;}finally{if(id===providerGeneration)providersLoading.value=false;}}
watch(providerType,loadProviders);
watch(section,()=>{familiesOpen.value=false;menuOpen.value=false;search.value='';providerType.value=section.value==='tutoring'?'tutoring':'counseling';});
watch([section,loading],()=>{if(!loading.value&&!error.value&&['home','providers','about','counseling','tutoring'].includes(section.value))loadProviders();},{immediate:true});
onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>{providerGeneration++;document.removeEventListener('pointerdown',outside);});
</script>
